  ('dd83c0ec-6c42-5bbe-9f01-ccefd7e91222', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '47U', 'USMA, PROFESSOR OF MILITARY INSTRUCTION AND ETHICS', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Responsible for serving as director of the Military Art and Science Program. Responsible for teaching undergraduate courses in Military Art and Science, supervision of faculty and academic programs, curriculum development, faculty development, service on faculty committees, and research.', 'c9316e756932dfdde53132cc0c3b80d32ea6938ad8f26a47c38d05f90bdfb3bc', 88, 88, null, 139, null, '2023-10-01', false, null),
