  ('9d696a9c-7816-5b49-9bc5-d277a219a23c', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '48P', 'ASIA-PACIFIC', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Positions which require a FAO with expertise, regional training, and language qualifications in the Asia-Pacific region.', 'ec406d78300d1dc4b5784d6795788425ee5bc8c2fd0891fde6cd41d6864df331', 93, 93, null, 155, null, null, false, null),
  ('774465fb-f0c3-5d57-9dc7-46b6133895df', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '48P', 'ASIA-PACIFIC', 'grades_authorized', null, null, 'Special grading of positions', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Positions graded MAJ and above. Select billets may be coded for:
