  ('a73c56f8-9b1f-5d83-9460-5c09135015d8', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '60B', 'NUCLEAR MEDICINE OFFICER', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Plans, conducts, interprets, and directs nuclear medical examinations and therapy including systemic administration of ionizing radiation, patient care, and activities concerned with the medical aspects of nuclear energy and bionucleonics.', '22694d3a76b495ce22d3ae1c60931bb171b1fe51a1dfba95b28e6232394b8595', 109, 109, null, 195, null, null, false, null),
  ('e43a2570-8e8f-5513-aad6-dfc54c8f7dc2', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '60C', 'PREVENTIVE MEDICINE OFFICER', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Determines status of, and conditions influencing health of military and appropriate civilian personnel; formulates and recommends measures for health improvements; and plans, coordinates, and directs a program designed to maintain health, improve physical fitness and prevent disease and injury.', 'fc7f717d66d958ffe72865496704f240cb7c72848da3082653a25d3e76cc28b4', 110, 110, null, 196, null, null, false, null),
  ('da8b35a4-6e3d-5e85-9094-4ef6b49fdb5c', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '60D', 'OCCUPATIONAL MEDICINE OFFICER', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Plans, directs and supervises occupational health programs for Department of Army civilian and military personnel.', 'a8bf1b78308393b90b0cc027e1ce42884c5aca582a43f16b612664ed8f5f7ad1', 110, 110, null, 197, null, null, false, null),
