  ('6c3d3fe2-8fff-5038-878d-2aa48d296843', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '60H', 'CARDIOLOGIST', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Examines, diagnoses, and treats or recommends, course of treatment or therapy for patients, with particular emphasis on disorders of the cardiovascular system.', 'eddbec02a1e341f8a7ba0ce75c5be7a379098a11b841a12f51279d21c0b31112', 110, 110, null, 199, null, null, false, null),
