  ('e36ae7a7-26c3-50d9-8faf-2559fa58e095', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '63E', 'ENDODONTIST', 'grades_authorized', null, null, 'Special grading of positions', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'For positions coded MAJ and above.', '00ac162d29777b76108cc5066b6e6d3bc91a03c44a27c9b180152ff61ce37aa7', 126, 126, null, 257, null, null, false, null),
  ('ca12196e-4925-5bfe-b6cf-cad42bd5efad', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '63E', 'ENDODONTIST', 'assignments', null, null, 'Unique duty positions', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', '(a) Endodontist.
(b) Program Director, Assistant Program Director, Advanced Specialty Education Program in Endodontics; Endodontics Mentor at AEGD 12-Month or 2-Year Programs.
(c) Chief of Endodontics.
(d) Endodontics Consultant, OTSG.
(e) Clinic Chief.', 'b9e103d1dd8a19293d3fa4dfcc395a4d19aeadc1fb7dfe3c601620b7ff2e72f0', 126, 126, null, 258, null, null, false, null),
  ('7ae37abd-7573-52e5-b492-66238a5d4955', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '63F', 'PROSTHODONTIST', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Examines, diagnoses, treatment plans, and rehabilitates the oral function, comfort, appearance, and health of patients with clinical conditions associated with missing teeth, severely worn dentitions, malocclusions, unaesthetic oral conditions, complete or partial edentulism, and/or loss of contiguous oral structures associated with traumatic, acquired, and congenital defects. Treatment of these conditions can be accomplished with fixed, removable, and/or implant retained dental prostheses. Treatment may range from single tooth replacement to full mouth reconstruction. TMD therapy as well as sleep disorders are supported with various modalities to include removable appliances.', 'f1acf3d59420c96380810c8c59b36e59c2f88f02d6265badf781b961dc98417f', 126, 126, null, 259, null, null, false, null),
  ('fc1e42f8-c912-55a5-8d32-5794d859c31d', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '63F', 'PROSTHODONTIST', 'grades_authorized', null, null, 'Special grading of positions', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'For positions coded MAJ and above.', '00ac162d29777b76108cc5066b6e6d3bc91a03c44a27c9b180152ff61ce37aa7', 126, 126, null, 260, null, null, false, null),
  ('eaa3d9c7-7308-5c48-b469-877e907b1ba0', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '63F', 'PROSTHODONTIST', 'assignments', null, null, 'Unique duty positions', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', '(a) Prosthodontist.
(b) Maxillofacial Prosthodontist.
(c) Program Director, Assistant Program Director, Training Officer: Advanced Specialty Education Program in Prosthodontics.
(d) Commander, Area Dental Laboratories.
(e) Instructor, Academy of Health Sciences.
(f) Prosthodontics Consultant, OTSG.
(g) Chief, Dental Laboratory Branch.
(h) Clinic Chief.', 'f3f57dda95f6c151199d65a5f191753778631fd43789dfcb6006be5030b75ca4', 127, 127, null, 261, null, null, false, null),
