  ('6366f100-9168-5702-99ad-c03c298423d0', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '63N', 'ORAL AND MAXILLOFACIAL SURGEON', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Examines, diagnoses, and treats or prescribes treatment for conditions involving diseases, defect, or injury to the oral and maxillofacial region including oral and maxillofacial surgical procedures and adjunctive care.', 'b1da3b05b1e289f659676b06bdd54b2da92db47c327a04e69155c20c56943038', 128, 128, null, 271, null, null, false, null),
