  ('eafbb005-daa2-5994-9f54-04005be22da5', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '63P', 'ORAL PATHOLOGIST', 'general_duties', null, null, 'Description of duties', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'Efficiently address both diagnosis and treatment of oral disease. Rapidly and reliably establish the critical connection between oral disease and systemic disease. Combine expertise in histopathologic diagnosis, clinical diagnosis, and treatment. Performs forensic dental identifications and provides forensic support to the Armed Forces Medical Examiner.', '27527680d1e1845b0af4986e563469f3b48c58cb1de2ea8111d9a78f73e13936', 129, 129, null, 274, null, null, false, null),
  ('45f3d82a-1cab-590e-887f-bced138ac84a', '7a6a4906-e811-5fb6-97fc-206842efb40c', 'Army', 'officer', '63P', 'ORAL PATHOLOGIST', 'grades_authorized', null, null, 'Special grading of positions', 'DA PAM 611-21, ch. 3 (officer branches and functional areas)', 'For positions coded MAJ and above.', '00ac162d29777b76108cc5066b6e6d3bc91a03c44a27c9b180152ff61ce37aa7', 129, 129, null, 275, null, null, false, null),
